<div class="row g-3 mb-4"><div class="col-md-7"><label class="form-label">Cover image</label><input class="form-control" type="file" name="cover_image" accept="image/jpeg,image/png,image/webp" data-preview="package-cover-preview">@if($package?->cover_image)<label class="form-check mt-2"><input class="form-check-input" type="checkbox" name="remove_cover_image" value="1"> Remove cover</label>@endif</div><div class="col-md-5"><x-admin.image-preview id="package-cover-preview" :src="$package?->cover_image?Storage::disk('public')->url($package->cover_image):null" /></div></div><div class="d-flex justify-content-between"><h3 class="h6">Gallery</h3><button class="btn btn-sm btn-outline-success" type="button" data-repeater-add="package-gallery" data-template="package-gallery-template">Add image</button></div><div id="package-gallery" data-next-index="{{ $package?->images->count()??0 }}">@foreach($package?->images??[] as $i=>$image)<div class="border rounded p-3 my-2" data-repeater-row><input type="hidden" name="gallery[{{ $i }}][id]" value="{{ $image->id }}"><div class="row g-2"><div class="col-md-2"><img class="w-100 rounded object-fit-cover" height="80" src="{{ Storage::disk('public')->url($image->image_path) }}" alt=""></div><div class="col-md-3"><input class="form-control" type="file" name="gallery[{{ $i }}][image]" accept="image/jpeg,image/png,image/webp"></div><div class="col-md-2"><input class="form-control" name="gallery[{{ $i }}][alt_text]" value="{{ $image->alt_text }}" placeholder="Alt text"></div><div class="col-md-2"><input class="form-control" name="gallery[{{ $i }}][caption]" value="{{ $image->caption }}" placeholder="Caption"></div><div class="col-md-1"><input class="form-control" type="number" name="gallery[{{ $i }}][display_order]" value="{{ $image->display_order }}"></div><div class="col-md-2"><label class="text-danger"><input type="checkbox" name="gallery[{{ $i }}][_remove]" value="1"> Remove</label></div></div></div>@endforeach</div><template id="package-gallery-template"><div class="border rounded p-3 my-2" data-repeater-row><div class="row g-2"><div class="col-md-4"><input class="form-control" type="file" name="gallery[__INDEX__][image]" required></div><div class="col-md-3"><input class="form-control" name="gallery[__INDEX__][alt_text]" placeholder="Alt text"></div><div class="col-md-3"><input class="form-control" name="gallery[__INDEX__][caption]" placeholder="Caption"></div><div class="col-md-1"><input class="form-control" type="number" name="gallery[__INDEX__][display_order]" value="0"></div><div class="col-md-1"><button type="button" class="btn btn-outline-danger" data-remove-new-row>×</button></div></div></div></template>
